"use client";

import { ScrollTrigger } from "./gsap";
import { useSmoothScroll } from "./use-smooth-scroll";
import { useReducedMotion } from "motion/react";
import { usePathname, useRouter } from "next/navigation";
import {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from "react";
import { MAIN_CONTENT_ID, ROUTE_TRANSITION_COVER_MS, ROUTE_TRANSITION_TIMEOUT_MS } from "./route-transition-types";
import type {
  RouteTransitionPhase,
  RouteTransitionRenderOverlay,
} from "./route-transition-types";
import { RouteTransitionContext, type RouteTransitionApi } from "./use-route-transition";

function focusMain() {
  const main = document.getElementById(MAIN_CONTENT_ID);
  if (main instanceof HTMLElement) {
    main.focus({ preventScroll: true });
  }
}

function refreshScrollScene() {
  ScrollTrigger.refresh();
}

export function RouteTransitionProvider({
  children,
  enabled = true,
  timeoutMs = ROUTE_TRANSITION_TIMEOUT_MS,
  renderOverlay,
}: {
  children: ReactNode;
  enabled?: boolean;
  timeoutMs?: number;
  renderOverlay?: RouteTransitionRenderOverlay;
}) {
  const router = useRouter();
  const pathname = usePathname();
  const reduce = Boolean(useReducedMotion());
  const smooth = useSmoothScroll();
  const [phase, setPhase] = useState<RouteTransitionPhase>("idle");
  const [href, setHref] = useState<string | null>(null);
  const pendingRef = useRef<string | null>(null);
  const timeoutRef = useRef<number>(0);
  const coverRef = useRef<number>(0);

  const clearTimers = useCallback(() => {
    window.clearTimeout(timeoutRef.current);
    window.clearTimeout(coverRef.current);
  }, []);

  const settle = useCallback(() => {
    clearTimers();
    pendingRef.current = null;
    setHref(null);
    setPhase("idle");
    smooth.start();
    smooth.resize();
    refreshScrollScene();
    focusMain();
  }, [clearTimers, smooth]);

  const fail = useCallback(() => {
    clearTimers();
    pendingRef.current = null;
    setHref(null);
    setPhase("idle");
    smooth.start();
  }, [clearTimers, smooth]);

  const navigate = useCallback(
    (nextHref: string) => {
      if (!enabled || reduce) {
        smooth.stop();
        router.push(nextHref);
        return;
      }
      clearTimers();
      pendingRef.current = nextHref;
      setHref(nextHref);
      setPhase("covering");
      smooth.stop();
      timeoutRef.current = window.setTimeout(() => {
        fail();
      }, timeoutMs);
      coverRef.current = window.setTimeout(() => {
        setPhase("waiting");
        try {
          router.push(nextHref);
        } catch {
          fail();
        }
      }, ROUTE_TRANSITION_COVER_MS);
    },
    [clearTimers, enabled, fail, reduce, router, smooth, timeoutMs],
  );

  const previousPathname = useRef(pathname);

  useEffect(() => {
    if (previousPathname.current === pathname) {
      return;
    }
    previousPathname.current = pathname;
    if (phase === "waiting") {
      setPhase("revealing");
      coverRef.current = window.setTimeout(() => {
        settle();
      }, ROUTE_TRANSITION_COVER_MS);
      return;
    }
    if (phase === "idle") {
      smooth.start();
      refreshScrollScene();
      focusMain();
    }
  }, [pathname, phase, settle, smooth]);

  useEffect(() => () => clearTimers(), [clearTimers]);

  const state = useMemo<RouteTransitionApi>(
    () => ({
      phase,
      href,
      enabled: enabled && !reduce,
      reducedMotion: reduce,
      navigate,
      fail,
    }),
    [enabled, fail, href, navigate, phase, reduce],
  );

  return (
    <RouteTransitionContext.Provider value={state}>
      {children}
      {enabled && !reduce && renderOverlay
        ? renderOverlay({
            phase,
            href,
            enabled: true,
            reducedMotion: false,
          })
        : null}
    </RouteTransitionContext.Provider>
  );
}

import type { ReactNode } from "react";

export type RouteTransitionPhase = "idle" | "covering" | "waiting" | "revealing";

export type RouteTransitionState = {
  phase: RouteTransitionPhase;
  href: string | null;
  enabled: boolean;
  reducedMotion: boolean;
};

export type RouteTransitionRenderOverlay = (state: RouteTransitionState) => ReactNode;

export const ROUTE_TRANSITION_TIMEOUT_MS = 8000;
export const ROUTE_TRANSITION_COVER_MS = 280;
export const MAIN_CONTENT_ID = "main-content";

"use client";

import { createContext, useContext } from "react";
import type { RouteTransitionState } from "./route-transition-types";

export type RouteTransitionApi = RouteTransitionState & {
  navigate: (href: string) => void;
  fail: () => void;
};

export const RouteTransitionContext = createContext<RouteTransitionApi | null>(null);

export function useRouteTransition(): RouteTransitionApi {
  const value = useContext(RouteTransitionContext);
  if (!value) {
    return {
      phase: "idle",
      href: null,
      enabled: false,
      reducedMotion: false,
      navigate: (href: string) => {
        window.location.assign(href);
      },
      fail: () => undefined,
    };
  }
  return value;
}

export type NavigationKind =
  | "internal"
  | "hash"
  | "external"
  | "download"
  | "new-tab"
  | "modified";

export type ClassifyNavigationInput = {
  href: string;
  currentPathname: string;
  target?: string | null;
  download?: boolean;
  metaKey?: boolean;
  ctrlKey?: boolean;
  shiftKey?: boolean;
  altKey?: boolean;
  button?: number;
};

export function classifyNavigation(input: ClassifyNavigationInput): NavigationKind {
  if (input.button != null && input.button !== 0) {
    return "modified";
  }
  if (input.metaKey || input.ctrlKey || input.shiftKey || input.altKey) {
    return "modified";
  }
  if (input.download) {
    return "download";
  }
  if (input.target === "_blank") {
    return "new-tab";
  }

  const href = input.href.trim();
  if (!href || href === "#") {
    return "hash";
  }
  if (
    href.startsWith("mailto:") ||
    href.startsWith("tel:") ||
    href.startsWith("sms:")
  ) {
    return "external";
  }

  if (href.startsWith("//")) {
    return "external";
  }
  try {
    const url = new URL(href, "http://cds.local");
    if (url.protocol === "http:" || url.protocol === "https:") {
      const isAbsolute = /^https?:\/\//i.test(href);
      if (isAbsolute) {
        return "external";
      }
    }
    if (href.startsWith("#") || (url.pathname === input.currentPathname && url.hash)) {
      return "hash";
    }
    return "internal";
  } catch {
    return "external";
  }
}

export function shouldInterceptNavigation(kind: NavigationKind): boolean {
  return kind === "internal";
}

"use client";

import { gsap } from "gsap";
import { CustomEase } from "gsap/CustomEase";
import { ScrollTrigger } from "gsap/ScrollTrigger";
import { useGSAP } from "@gsap/react";

let registered = false;
const plugins = [ScrollTrigger, useGSAP, CustomEase];

export function registerGsap() {
  if (registered || typeof window === "undefined") {
    return;
  }
  gsap.registerPlugin(...plugins);
  registered = true;
}

export function reducedMotionMatchMedia() {
  return gsap.matchMedia();
}

export { CustomEase, gsap, ScrollTrigger, useGSAP };

"use client";

import type Lenis from "lenis";
import { createContext, useContext } from "react";
import { FINE_POINTER_QUERY } from "./motion-policy";
import { getReducedMotionSnapshot } from "./reduced-motion";
import {
  resolveSmoothScrollMode,
  type SmoothScrollMode,
} from "./smooth-scroll-options";

export type SmoothScrollToTarget = number | string | HTMLElement;

export type SmoothScrollToOptions = {
  immediate?: boolean;
  offset?: number;
  lock?: boolean;
};

export type SmoothScrollApi = {
  lenis: Lenis | null;
  mode: SmoothScrollMode;
  scrollTo: (target: SmoothScrollToTarget, options?: SmoothScrollToOptions) => void;
  start: () => void;
  stop: () => void;
  resize: () => void;
};

export const SmoothScrollContext = createContext<SmoothScrollApi | null>(null);

function nativeScrollTo(
  target: SmoothScrollToTarget,
  options?: SmoothScrollToOptions,
) {
  if (typeof window === "undefined") {
    return;
  }
  const behavior = options?.immediate ? "auto" : "smooth";
  if (typeof target === "number") {
    window.scrollTo({ top: target, behavior });
    return;
  }
  if (typeof target === "string") {
    if (target === "top" || target === "start") {
      window.scrollTo({ top: 0, behavior });
      return;
    }
    const node = document.querySelector(target);
    node?.scrollIntoView({ behavior, block: "start" });
    return;
  }
  target.scrollIntoView({ behavior, block: "start" });
}

export const nativeSmoothScrollApi: SmoothScrollApi = {
  lenis: null,
  mode: "reduced-motion",
  scrollTo: nativeScrollTo,
  start: () => undefined,
  stop: () => undefined,
  resize: () => undefined,
};

/**
 * Control API for the app-level SmoothScrollProvider.
 * Outside the provider this returns native window scrolling (lenis is null).
 */
export function useSmoothScroll(): SmoothScrollApi {
  const value = useContext(SmoothScrollContext);
  if (value) {
    return value;
  }
  const reduce = getReducedMotionSnapshot();
  const finePointer =
    typeof window !== "undefined" &&
    window.matchMedia(FINE_POINTER_QUERY).matches;
  return {
    ...nativeSmoothScrollApi,
    mode: resolveSmoothScrollMode({ reduce, finePointer }),
  };
}

import { FINE_POINTER_QUERY } from "./motion-policy";

export type SmoothScrollMode = "smooth" | "native-touch" | "reduced-motion";

export type SmoothScrollOptions = {
  lerp: number;
  anchors: boolean;
  stopInertiaOnNavigate: boolean;
  syncTouch: boolean;
  smoothWheel: boolean;
  autoRaf: boolean;
  respectReducedMotion: boolean;
};

export const SMOOTH_SCROLL_DEFAULTS: SmoothScrollOptions = {
  lerp: 0.1,
  anchors: true,
  stopInertiaOnNavigate: true,
  syncTouch: false,
  smoothWheel: true,
  autoRaf: false,
  respectReducedMotion: true,
};

export const LENIS_PREVENT_SELECTOR =
  "[data-lenis-prevent], [data-radix-dialog-content], [role='dialog']";

export function resolveSmoothScrollMode(options: {
  reduce: boolean | null | undefined;
  finePointer: boolean;
}): SmoothScrollMode {
  if (options.reduce) {
    return "reduced-motion";
  }
  if (!options.finePointer) {
    return "native-touch";
  }
  return "smooth";
}

export function shouldEnableLenis(mode: SmoothScrollMode): boolean {
  return mode === "smooth";
}

export function shouldPreventLenis(node: HTMLElement): boolean {
  return Boolean(node.closest(LENIS_PREVENT_SELECTOR));
}

export { FINE_POINTER_QUERY };

export const FINE_POINTER_QUERY = "(pointer: fine) and (hover: hover)";

export function shouldAnimateMotion(
  reduce: boolean | null | undefined,
): boolean {
  return !reduce;
}

export function shouldEnableParallax(options: {
  reduce: boolean | null | undefined;
  viewportWidth: number | null;
  disableBelow?: number;
}): boolean {
  if (!shouldAnimateMotion(options.reduce)) {
    return false;
  }
  if (
    options.disableBelow != null &&
    options.viewportWidth != null &&
    options.viewportWidth < options.disableBelow
  ) {
    return false;
  }
  return true;
}

export function shouldEnableMagnetic(options: {
  reduce: boolean | null | undefined;
  finePointer: boolean;
  pointerType?: string;
}): boolean {
  if (!shouldAnimateMotion(options.reduce)) {
    return false;
  }
  if (!options.finePointer) {
    return false;
  }
  if (
    options.pointerType &&
    options.pointerType !== "mouse" &&
    options.pointerType !== "pen"
  ) {
    return false;
  }
  return true;
}

export function shouldEnablePointerAccent(options: {
  enabled: boolean;
  reduce: boolean | null | undefined;
  finePointer: boolean;
  pointerType?: string;
}): boolean {
  if (!options.enabled) {
    return false;
  }
  return shouldEnableMagnetic({
    reduce: options.reduce,
    finePointer: options.finePointer,
    pointerType: options.pointerType,
  });
}

"use client";

import { useReducedMotion } from "motion/react";

export const reducedMotionQuery = "(prefers-reduced-motion: reduce)";

export function getReducedMotionSnapshot(): boolean {
  if (typeof window === "undefined") {
    return false;
  }
  return window.matchMedia(reducedMotionQuery).matches;
}

export function usePrefersReducedMotion(): boolean {
  return Boolean(useReducedMotion());
}

export const reducedMotionCss = {
  query: reducedMotionQuery,
  disableTransitions: `
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}
`,
};
